_has_http.source:
def _has_http(self, filename: str) -> bool:
    parser = self.parse_cisco_ios_config_file(filename)
    http_enable = parser.find_objects('ip http server')
    http_disable = parser.find_objects('no ip http server')
    if len(http_enable) > 0:
        return True
    elif len(http_disable) > 0:
        return False
    else:
        return True

get_cisco_ios_ssh_reties.source:
def get_cisco_ios_ssh_reties(self, filename: str):
    retries = self._get_cisco_ios_ssh_retries(filename)
    if retries == '' or retries > 5:
        return CiscoIOSIssue('SSH retries misconfiguration', 'The SSH service must have a defined number of retries, the recommended is between 0 and 5.', 'Set a retries number allows to reduce the bruteforce and dictionary attacks. If a retry number is defined, the attacker can not test with an user multiple passwords.', 'This issue improve the hardening of passwords in the network device.', 'This can be configured with the following command: ip ssh authentication-retries <retry-number>.')
    return None

get_cisco_ios_telnet.source:
def get_cisco_ios_telnet(filename: str) -> bool:
    parser = parse_cisco_ios_config_file(filename)
    transport_disable = parser.find_objects('transport input none')
    ssh_enable = parser.find_objects('transport input ssh')
    telnet_disable = parser.find_objects('no transport input telnet')
    if len(transport_disable) > 0 or len(ssh_enable) > 0 or len(telnet_disable) > 0:
        return False
    else:
        return True
